package com.northstarbank.console.web;import com.northstarbank.console.domain.*;import com.northstarbank.console.security.AuthorizationService;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;
@Controller public class DashboardController{private final ServiceRequestRepository requests;private final FinancialRepository financial;private final AuthorizationService auth;public DashboardController(ServiceRequestRepository r,FinancialRepository f,AuthorizationService a){requests=r;financial=f;auth=a;}@GetMapping({"/","/dashboard"})String dashboard(Model m){auth.require("DASHBOARD",null,false);m.addAttribute("openRequests",requests.countByStatus("open"));m.addAttribute("inProgress",requests.countByStatus("in_progress"));m.addAttribute("pending",financial.findTop50ByStatusOrderByRequestedAtAsc("pending_approval").size());return"dashboard";}@GetMapping("/profile")String profile(){auth.require("PROFILE",null,false);return"profile";}@PostMapping("/profile")String update(@RequestParam @jakarta.validation.constraints.Size(max=40)String displayName,org.springframework.web.servlet.mvc.support.RedirectAttributes r){auth.require("PROFILE",null,false);r.addFlashAttribute("success","Profile updated");return"redirect:/profile";}@GetMapping("/regional")String regional(){auth.require("DASHBOARD",null,false);return"regional";}}
